css:
/* Terminal — a TUI in the browser, built on the clean base (no native chrome). */
.shell { background: #000 !important; color: #39ff14; font-family: 'Courier New', ui-monospace, monospace; }
.shell :is(h1, h2, h3, strong, button, input, select, textarea, p, small, a) { font-family: inherit !important; }
.shell :is(h1, h2, h3, .section-title, .rumahl-settings__section-title) { text-transform: uppercase !important; letter-spacing: 0.08em !important; }
.shell :is(.shell-window, .rumahl-window-surface, .rumahl-settings, .taskbar, .os-dock, .menubar, .topbar__island) { background: #000 !important; border: 1px solid #39ff14 !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
.shell :is(.topbar__island, .menubar, .taskbar) { color: #39ff14 !important; }
.shell :is(.btn, button, input, select, textarea) { border: 1px solid #39ff14 !important; border-radius: 0 !important; background: #000 !important; color: #39ff14 !important; box-shadow: none !important; }
.shell :is(.btn, button):hover { background: #39ff14 !important; color: #000 !important; }
.shell :is(.rumahl-group, .settings-group, .rumahl-menu, .rumahl-popover, .rumahl-notice, .rumahl-chip, .rumahl-badge, .rumahl-tray) { border: 1px solid #124a0a !important; border-radius: 0 !important; background: transparent !important; box-shadow: none !important; }
.shell :is(input[role='switch'], .rumahl-choice input) { border: 1px solid #39ff14 !important; border-radius: 0 !important; background: #000 !important; box-shadow: none !important; }
.shell input[role='switch']:checked, .shell .rumahl-choice input:checked { background: #39ff14 !important; }
.shell :is(input[role='switch'], .rumahl-choice input)::before { border-radius: 0 !important; background: #39ff14 !important; }
.shell :focus-visible { outline: 1px dashed #39ff14 !important; outline-offset: 2px !important; }
.shell ::selection { background: #39ff14; color: #000; }
